{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The 'encrypt_at_rest' block has 'enabled' set to false, which means data stored in the Elasticsearch domain is not encrypted at rest. This poses a risk of data exposure if the storage is compromised."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Ensure all Elasticsearch has node-to-node encryption enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Node-to-node encryption is not configured in this Elasticsearch domain. Without it, data transmitted between nodes is not encrypted, increasing the risk of interception."
    },
    {
      "check_id": "CKV_AWS_317",
      "title": "Ensure Elasticsearch Domain Audit Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Audit logging is not enabled for this Elasticsearch domain. Without audit logs, it is difficult to track access and changes to the domain, which can hinder incident response and compliance efforts."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Logging is not configured for this Elasticsearch domain. Without logging, operational issues and security events may go undetected."
    },
    {
      "check_id": "CKV_AWS_247",
      "title": "Ensure all data stored in the Elasticsearch is encrypted with a CMK",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain is not configured to use a customer-managed key (CMK) for encryption at rest. Using a CMK provides better control over encryption keys and meets compliance requirements."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Verify Elasticsearch domain is using an up to date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain does not specify a TLS security policy. Using an outdated or default TLS policy may expose the domain to vulnerabilities."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Ensure ElasticSearch/OpenSearch has dedicated master node enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain does not have dedicated master nodes configured. Without dedicated master nodes, the cluster may face stability and availability issues under load."
    },
    {
      "check_id": "CKV2_AWS_52",
      "title": "Ensure AWS ElasticSearch/OpenSearch Fine-grained access control is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Fine-grained access control is not enabled for this Elasticsearch domain. Without it, access to the domain cannot be restricted at a granular level, increasing the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_elasticsearch_domain\" \"log_search_database\" {\n  domain_name           = \"enterprise-log-analytics-es\"\n  elasticsearch_version = \"7.10\"\n  cluster_config {\n    instance_type  = var.elasticsearch_instance_type\n    instance_count = 2\n    dedicated_master_enabled = true\n    dedicated_master_type = var.elasticsearch_master_instance_type\n    dedicated_master_count = 3\n  }\n  vpc_options {\n    subnet_ids         = [aws_subnet.data_subnet_az1.id]\n    security_group_ids = [aws_security_group.elasticsearch_sg.id]\n  }\n  ebs_options {\n    ebs_enabled = true\n    volume_size = 20\n    volume_type = \"gp2\"\n  }\n  encrypt_at_rest {\n    enabled = true\n    kms_key_id = aws_kms_key.elasticsearch_kms_key.arn\n  }\n  node_to_node_encryption {\n    enabled = true\n  }\n  log_publishing_options {\n    log_type = \"AUDIT_LOGS\"\n    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_audit_logs.arn\n  }\n  advanced_security_options {\n    enabled = true\n    internal_user_database_enabled = true\n  }\n  domain_endpoint_options {\n    enforce_https = true\n    tls_security_policy = \"Policy-Min-TLS-1-2-2019-07\"\n  }\n}",
  "fix_summary": "Enabled encryption at rest with a CMK, node-to-node encryption, audit logging, and fine-grained access control. Configured dedicated master nodes for high availability and enforced an up-to-date TLS policy."
}
